function draw({board,width,height,params}) {
  const C=VisualBook.palette, lam=params.lambda;
  const data=w=>0.5*(w-2)*(w-2), penalty=w=>0.5*lam*w*w, total=w=>data(w)+penalty(w);
  const optimum=2/(1+lam), mobile=width<500;
  const labels=[['data','数据损失',C.blue],['penalty','惩罚',C.orange],['total','总目标',C.ink]];
  labels.forEach((q,i)=>{let x=mobile?10+i*105:30+i*170;board.line('legend-'+q[0],x,20,x+20,20,q[2],2.5);board.text('legend-text-'+q[0],q[1],x+27,25,{size:14,color:q[2]});});
  const f=board.axes('loss-axes',{xDomain:[-0.5,2.5],yDomain:[0,5.3],xLabel:'权重 w',yLabel:'目标值',box:[48,58,width-25,height-85],grid:false});
  const xs=Array.from({length:151},(_,i)=>-0.5+3*i/150);
  board.curve('data-curve',f,xs.map(w=>[w,data(w)]),{color:C.blue,width:2});
  board.curve('penalty-curve',f,xs.map(w=>[w,penalty(w)]),{color:C.orange,width:2});
  board.curve('total-curve',f,xs.map(w=>[w,total(w)]),{color:C.ink,width:2.6});
  board.line('minimum-guide',f.x(optimum),f.y(0),f.x(optimum),f.y(total(optimum)),C.muted,1,0.65);
  board.mark('unregularized-minimum','circle',{cx:f.x(2),cy:f.y(0),r:4,fill:C.paper,stroke:C.blue,'stroke-width':2});
  board.circle('regularized-minimum',f.x(optimum),f.y(total(optimum)),5,C.ink);
  board.text('minimum-value','最优 w = '+optimum.toFixed(2),mobile?12:30,height-29,{size:16,color:C.ink});
  board.text('minimum-losses','数据 '+data(optimum).toFixed(3)+'  ·  惩罚 '+penalty(optimum).toFixed(3),mobile?12:width-28,mobile?height-6:height-29,{size:14,color:C.muted,anchor:mobile?'start':'end'});
  return {example:{x:1,y:2,bias:0},lambda:lam,optimum,dataLoss:data(optimum),penalty:penalty(optimum),totalLoss:total(optimum),derivativeAtOptimum:(optimum-2)+lam*optimum,unregularizedOptimum:2};
}

function draw({board,width,height,params}) {
  const C=VisualBook.palette, eta=params.eta,lam=params.lambda;
  const old=[2,1],g=[-1,2],factor=1-eta*lam;
  const shrunk=old.map(v=>factor*v),dataStep=g.map(v=>-eta*v),next=shrunk.map((v,i)=>v+dataStep[i]);
  const mobile=width<500;
  [['shrink','衰减步',C.orange],['data','数据步',C.blue]].forEach((q,i)=>{const x=mobile?16+i*155:30+i*180;board.line('legend-'+q[0],x,20,x+23,20,q[2],2.5);board.text('legend-label-'+q[0],q[1],x+30,25,{color:q[2],size:14});});
  const f=board.axes('weight-space',{xDomain:[-0.2,2.9],yDomain:[-0.9,1.45],equalUnits:true,xLabel:'w₁',yLabel:'w₂',box:[45,51,width-27,height-95],grid:false});
  board.vector('old-vector',f,[0,0],old,{color:C.muted});
  board.vector('shrink-step',f,old,shrunk,{color:C.orange});
  board.vector('data-step',f,shrunk,next,{color:C.blue});
  board.mark('old-point','circle',{cx:f.x(old[0]),cy:f.y(old[1]),r:4,fill:C.paper,stroke:C.muted,'stroke-width':2});
  board.circle('shrunk-point',f.x(shrunk[0]),f.y(shrunk[1]),3,C.orange);
  board.circle('next-point',f.x(next[0]),f.y(next[1]),5,C.ink);
  board.text('old-label','旧',f.x(old[0])+10,f.y(old[1])-10,{size:14,color:C.muted});
  board.text('new-label','新',f.x(next[0])+10,f.y(next[1])+20,{size:14,color:C.ink});
  board.text('factor','收缩系数 '+factor.toFixed(2),mobile?12:30,height-42,{size:15,color:C.orange});
  board.text('norm','范数 2.236 → '+Math.hypot(...next).toFixed(3),mobile?12:width-28,mobile?height-19:height-42,{size:15,color:C.ink,anchor:mobile?'start':'end'});
  return {old,dataGradient:g,eta,lambda:lam,shrinkFactor:factor,shrinkStep:old.map(v=>-eta*lam*v),shrunk,dataStep,next,oldNorm:Math.hypot(...old),nextNorm:Math.hypot(...next),convention:'旧位置的数据梯度；箭头为一次SGD更新的代数分解，不是两次优化'};
}
